CREATE TABLE "court_owner_reviews" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "court_owner_reviews_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"facility_id" bigint,
	"court_id" bigint,
	"kind" varchar NOT NULL,
	"submitted_values" jsonb NOT NULL,
	"status" varchar NOT NULL,
	"submitted_by" bigint NOT NULL,
	"reviewed_by" bigint,
	"rejection_reason" text,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"reviewed_at" timestamp,
	CONSTRAINT "chk_owner_review_target" CHECK (("court_owner_reviews"."facility_id" IS NOT NULL) <> ("court_owner_reviews"."court_id" IS NOT NULL)),
	CONSTRAINT "chk_owner_review_kind" CHECK ("court_owner_reviews"."kind" IN ('ONBOARDING', 'ADDRESS_CHANGE') AND ("court_owner_reviews"."kind" <> 'ADDRESS_CHANGE' OR "court_owner_reviews"."facility_id" IS NOT NULL)),
	CONSTRAINT "chk_owner_review_status" CHECK ("court_owner_reviews"."status" IN ('PENDING', 'APPROVED', 'REJECTED')),
	CONSTRAINT "chk_owner_review_decision" CHECK (("court_owner_reviews"."status" = 'PENDING' AND "court_owner_reviews"."reviewed_by" IS NULL AND "court_owner_reviews"."reviewed_at" IS NULL AND "court_owner_reviews"."rejection_reason" IS NULL) OR ("court_owner_reviews"."status" = 'APPROVED' AND "court_owner_reviews"."reviewed_by" IS NOT NULL AND "court_owner_reviews"."reviewed_at" IS NOT NULL AND "court_owner_reviews"."rejection_reason" IS NULL) OR ("court_owner_reviews"."status" = 'REJECTED' AND "court_owner_reviews"."reviewed_by" IS NOT NULL AND "court_owner_reviews"."reviewed_at" IS NOT NULL AND "court_owner_reviews"."rejection_reason" IS NOT NULL AND length(trim("court_owner_reviews"."rejection_reason")) > 0))
);
--> statement-breakpoint
CREATE TABLE "court_slot_blocks" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "court_slot_blocks_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"court_id" bigint NOT NULL,
	"booking_date" date NOT NULL,
	"start_time" time NOT NULL,
	"end_time" time NOT NULL,
	"block_range" "tsrange" GENERATED ALWAYS AS (tsrange(booking_date + start_time, booking_date + end_time, '[)')) STORED,
	"reason" text NOT NULL,
	"status" varchar NOT NULL,
	"created_by" bigint NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "chk_court_slot_block_range" CHECK ("court_slot_blocks"."end_time" > "court_slot_blocks"."start_time"),
	CONSTRAINT "chk_court_slot_block_status" CHECK ("court_slot_blocks"."status" IN ('ACTIVE', 'RELEASED')),
	CONSTRAINT "chk_court_slot_block_reason" CHECK (length(trim("court_slot_blocks"."reason")) > 0)
);
